export * from "./restaurant-card";
export * from "./menu-item-card";
export * from "./reward-card";
export * from "./transaction-row";
export * from "./wallet-card";
export * from "./food-card";
export * from "./order-card";
export * from "./transaction-card";

import type { MenuItem } from "@/types/payplate";
import { MenuItemCard } from "./menu-item-card";

export function FoodCard({ item }: { item: MenuItem }) {
  return <MenuItemCard item={item} />;
}

import { Card } from "@/components/ui/card";
import type { MenuItem } from "@/types/payplate";
import { MenuItemCard } from "./menu-item-card";

export function OrderCard({ items }: { items: MenuItem[] }) {
  const total = items.reduce((s, i) => s + i.priceCents, 0);
  return (
    <Card>
      <h3 className="font-heading text-lg font-black">Order summary</h3>
      <div className="mt-4 space-y-3">
        {items.map((it) => (
          <MenuItemCard key={it.id} item={it} />
        ))}
      </div>
      <div className="mt-4 flex items-center justify-between">
        <p className="font-bold">Total</p>
        <p className="font-heading font-black">{new Intl.NumberFormat("en-ZA", { style: "currency", currency: "ZAR" }).format(total / 100)}</p>
      </div>
    </Card>
  );
}

import { motion } from "framer-motion";
import { Coffee, Beef, CreditCard, Pizza, Diamond } from "lucide-react";
import type { Reward } from "@/types/payplate";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { cn } from "@/lib/utils";

const tierConfig = {
  bronze: { bg: "from-amber-700 to-amber-900", glow: "shadow-[0_0_30px_rgba(180,83,9,0.3)]", label: "text-amber-600" },
  silver: { bg: "from-slate-300 to-slate-500", glow: "shadow-[0_0_30px_rgba(148,163,184,0.3)]", label: "text-slate-400" },
  gold: { bg: "from-yellow-400 to-yellow-600", glow: "shadow-[0_0_30px_rgba(250,204,21,0.4)]", label: "text-yellow-500" },
  diamond: { bg: "from-cyan-300 to-blue-500", glow: "shadow-[0_0_40px_rgba(59,130,246,0.4)]", label: "text-cyan-400" },
};

const iconMap: Record<string, React.ReactNode> = {
  coffee: <Coffee size={28} />,
  fries: <Beef size={28} />,
  credit: <CreditCard size={28} />,
  pizza: <Pizza size={28} />,
  diamond: <Diamond size={28} />,
};

export function RewardCard({ reward, onRedeem }: { reward: Reward; onRedeem?: () => void }) {
  const reduced = usePrefersReducedMotion();
  const config = tierConfig[reward.tier];

  return (
    <Card className="overflow-hidden p-0">
      <div className={cn("relative bg-gradient-to-br p-5", config.bg, config.glow)}>
        <div className="absolute right-3 top-3 rounded-full bg-white/20 px-2 py-1 text-[10px] font-black uppercase tracking-wide text-white">
          {reward.tier}
        </div>
        <div className="flex items-center gap-3">
          <motion.div
            animate={reduced ? undefined : { rotateY: [0, 360] }}
            transition={{ duration: 6, repeat: Infinity, ease: "linear" }}
            className="grid size-14 place-items-center rounded-2xl bg-white/20 text-white backdrop-blur-sm"
          >
            {iconMap[reward.icon]}
          </motion.div>
          <div>
            <h4 className="font-heading text-lg font-black text-white">{reward.title}</h4>
            <p className="text-xs text-white/80">{reward.description}</p>
          </div>
        </div>
      </div>

      <div className="p-4">
        {reward.isEarned ? (
          <Button variant="primary" className="w-full" onClick={onRedeem}>
            Redeem · {reward.pointsCost} pts
          </Button>
        ) : (
          <div className="space-y-2">
            <div className="flex items-center justify-between text-xs font-bold">
              <span className="text-muted-foreground">{reward.pointsCost} pts needed</span>
              <span className={config.label}>{reward.progressPercent ?? 0}%</span>
            </div>
            <div className="h-2 overflow-hidden rounded-full bg-muted">
              <div
                className="h-full rounded-full bg-primary transition-all duration-500"
                style={{ width: `${reward.progressPercent ?? 0}%` }}
              />
            </div>
          </div>
        )}
      </div>
    </Card>
  );
}

import { Plus, Minus, Clock, Flame, Star, Heart } from "lucide-react";
import type { MenuItem } from "@/types/payplate";
import { formatRand } from "@/services/payplate-data";
import { Badge } from "@/components/ui/badge";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { useCart } from "@/contexts/cart-context";
import { useToast } from "@/contexts/toast-context";
import { motion } from "framer-motion";
import { useState } from "react";
import { cn } from "@/lib/utils";

export function MenuItemCard({ item }: { item: MenuItem }) {
  const reduced = usePrefersReducedMotion();
  const { addItem, getQuantity, updateQuantity } = useCart();
  const { showToast } = useToast();
  const [isFav, setIsFav] = useState(false);
  const quantity = getQuantity(item.id);

  function handleAdd() {
    addItem(item);
    showToast(`${item.name} added to cart`, "success");
  }

  return (
    <motion.div
      whileHover={!reduced ? { y: -4 } : undefined}
      transition={{ type: "spring", stiffness: 320, damping: 28 }}
      className="h-full"
    >
      <div className="flex h-full gap-3 rounded-2xl border border-border bg-card p-3 shadow-card transition-shadow duration-300 hover:shadow-lift">
        {/* Image */}
        <div className="relative shrink-0">
          <img
            src={item.image}
            alt={item.name}
            className="size-24 rounded-xl object-cover"
            loading="lazy"
          />
          {item.isPopular && (
            <div className="absolute -left-1 -top-1 flex items-center gap-0.5 rounded-full bg-card px-1.5 py-0.5 shadow-soft ring-1 ring-border">
              <Flame size={10} className="text-warning" />
              <span className="text-[9px] font-black">Popular</span>
            </div>
          )}
          <button
            onClick={() => setIsFav(!isFav)}
            aria-label={`Favourite ${item.name}`}
            className="absolute bottom-1 right-1 grid size-6 place-items-center rounded-full bg-card/90 backdrop-blur-sm shadow-soft"
          >
            <Heart size={12} className={cn("transition-colors", isFav ? "fill-danger text-danger" : "text-muted-foreground")} />
          </button>
        </div>

        {/* Content */}
        <div className="flex min-w-0 flex-1 flex-col justify-between">
          <div className="space-y-1">
            <div className="flex items-start justify-between gap-1">
              <h3 className="truncate font-heading text-sm font-black leading-tight">{item.name}</h3>
              {item.rating && (
                <span className="inline-flex shrink-0 items-center gap-0.5 text-xs font-bold text-rewards">
                  <Star size={11} fill="currentColor" /> {item.rating}
                </span>
              )}
            </div>
            <p className="line-clamp-2 text-xs leading-relaxed text-muted-foreground">{item.description}</p>
            <div className="flex flex-wrap items-center gap-1.5 text-xs text-muted-foreground">
              <span className="inline-flex items-center gap-0.5"><Clock size={10} /> {item.prepTimeMinutes}min</span>
              {item.calories && <span>· {item.calories} cal</span>}
              {item.dietaryTags.slice(0, 1).map((tag) => (
                <Badge key={tag} className="text-[9px] px-1.5 py-0">{tag}</Badge>
              ))}
            </div>
          </div>

          <div className="flex items-center justify-between gap-2 pt-1">
            <p className="font-heading text-base font-black tabular-nums">{formatRand(item.priceCents)}</p>
            {quantity > 0 ? (
              <motion.div
                initial={reduced ? undefined : { scale: 0.8 }}
                animate={{ scale: 1 }}
                className="flex items-center gap-1.5"
              >
                <button
                  onClick={() => updateQuantity(item.id, quantity - 1)}
                  className="grid size-8 place-items-center rounded-xl bg-muted transition-transform active:scale-90"
                  aria-label="Decrease quantity"
                >
                  <Minus size={14} />
                </button>
                <span className="min-w-5 text-center font-heading text-sm font-black tabular-nums">{quantity}</span>
                <button
                  onClick={() => updateQuantity(item.id, quantity + 1)}
                  className="grid size-8 place-items-center rounded-xl bg-primary text-white shadow-lift transition-transform active:scale-90"
                  aria-label="Increase quantity"
                >
                  <Plus size={14} />
                </button>
              </motion.div>
            ) : (
              <motion.button
                whileTap={!reduced ? { scale: 0.9 } : undefined}
                onClick={handleAdd}
                aria-label={`Add ${item.name} to cart`}
                className="grid size-9 place-items-center rounded-xl bg-primary text-white shadow-lift transition-transform duration-200 hover:-translate-y-0.5 active:scale-90"
              >
                <Plus size={18} />
              </motion.button>
            )}
          </div>
        </div>
      </div>
    </motion.div>
  );
}

import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import { useEffect, useRef } from "react";
import { Wallet } from "lucide-react";
import { formatRand } from "@/services/payplate-data";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { cn } from "@/lib/utils";

type WalletCardProps = {
  balanceCents: number;
  rewardPoints: number;
  tier: string;
  className?: string;
};

export function WalletCard({ balanceCents, rewardPoints, tier, className }: WalletCardProps) {
  const reduced = usePrefersReducedMotion();
  const ref = useRef<HTMLDivElement>(null);

  const rotateX = useSpring(useMotionValue(0), { stiffness: 300, damping: 30 });
  const rotateY = useSpring(useMotionValue(0), { stiffness: 300, damping: 30 });

  function handleMouse(e: React.MouseEvent) {
    if (reduced || !ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    rotateX.set(((cy - e.clientY) / rect.height) * 20);
    rotateY.set(((e.clientX - cx) / rect.width) * 20);
  }

  function handleTouch(e: React.TouchEvent) {
    if (reduced || !ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const touch = e.touches[0];
    rotateX.set(((cy - touch.clientY) / rect.height) * 20);
    rotateY.set(((touch.clientX - cx) / rect.width) * 20);
  }

  function reset() {
    rotateX.set(0);
    rotateY.set(0);
  }

  const transform = useTransform([rotateX, rotateY], ([rx, ry]) =>
    `perspective(1000px) rotateX(${rx}deg) rotateY(${ry}deg)`,
  );

  return (
    <motion.div
      ref={ref}
      onMouseMove={handleMouse}
      onMouseLeave={reset}
      onTouchMove={handleTouch}
      onTouchEnd={reset}
      style={{ transform }}
      className={cn(
        "relative overflow-hidden rounded-3xl bg-gradient-to-br from-primary via-primary-600 to-dark p-6 text-white shadow-lift",
        className,
      )}
    >
      {/* Glass reflection */}
      <div className="pointer-events-none absolute -right-12 -top-12 size-48 rounded-full bg-white/10 blur-2xl" />
      <div className="pointer-events-none absolute -bottom-16 -left-8 size-40 rounded-full bg-white/5 blur-2xl" />

      <div className="relative flex items-start justify-between">
        <div>
          <p className="text-xs font-bold uppercase tracking-wide text-white/70">PayPlate Wallet</p>
          <div className="mt-3 flex items-center gap-2">
            <Wallet size={18} className="text-white/80" />
            <span className="text-xs font-bold capitalize text-white/70">{tier} tier</span>
          </div>
        </div>
        <div className="grid size-10 place-items-center rounded-xl bg-white/15 backdrop-blur-sm">
          <Wallet size={18} />
        </div>
      </div>

      <div className="relative mt-8">
        <motion.p
          key={balanceCents}
          initial={reduced ? undefined : { opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          className="font-heading text-3xl font-black tabular-nums"
        >
          {formatRand(balanceCents)}
        </motion.p>
        <p className="mt-1 text-xs text-white/70">{rewardPoints} reward points</p>
      </div>

      <div className="relative mt-6 flex items-center justify-between">
        <div className="space-y-1">
          <div className="h-1 w-12 rounded-full bg-white/30" />
          <div className="h-1 w-8 rounded-full bg-white/20" />
        </div>
        <div className="rounded-lg bg-white/15 px-3 py-1.5 text-xs font-black backdrop-blur-sm">
          •••• 2026
        </div>
      </div>
    </motion.div>
  );
}
